#include <stdio.h>
#include <string.h>
#include "decNumber.h"
#include "decContext.h"

static int cmp(const char *a, const char *b) {
  decNumber da, db, res;
  decContext ctx;
  decContextDefault(&ctx, DEC_INIT_DECIMAL128);
  ctx.digits = DEC_MAX_DIGITS - 1;
  ctx.emax = DEC_MAX_EMAX;
  ctx.emin = DEC_MIN_EMIN;
  ctx.traps = 0;
  ctx.status = 0;
  decNumberFromString(&da, a, &ctx);
  decNumberFromString(&db, b, &ctx);
  decNumberCompare(&res, &da, &db, &ctx);
  if (decNumberIsZero(&res)) return 0;
  return decNumberIsNegative(&res) ? -1 : 1;
}

int main(void) {
  printf("%d\n", cmp("3E506760210", "63E-6855002263"));
  printf("%d\n", cmp("63E-6855002263", "3E506760210"));
  printf("%d\n", cmp("-3E506760210", "-63E-6855002263"));
  printf("%d\n", cmp("1e999999999", "1e-1147483648"));
  return 0;
}

